import translation_client

def batch_translate(texts, source_language, target_language, config=None):
    translations = []
    for text in texts:
        payload = {'text': text, 'source_language': source_language, 'target_language': target_language}
        translation = translation_client.translate_text(payload, config)
        translations.append(translation['text'])
    return translations

import translation_client

def translate_dictionary_values(dictionary, source_language, target_language, config=None):
    translated_dictionary = {}
    for key, value in dictionary.items():
        translated_value = translation_client.translate_text({'text': value, 'source_language': source_language, 'target_language': target_language}, config)['text']
        translated_dictionary[key] = translated_value
    return translated_dictionary

def normalize_payload(payload):
    return {'text': payload['text'], 'source_language': payload['source_language'], 'target_language': payload['target_language']}

def normalize_response(response):
    return {'text': response['text'], 'source_language': response['source_language'], 'target_language': response['target_language']}
